-- ── verify (read-only, safe to re-run) ───────────────────────────────

-- the nine rows as seeded:
select name, slug, tool_type, status, icon_emoji, folksonomy_type, home
from public.awen
where slug in ('the-effect', 'the-graph', 'the-dynamics', 'the-transition',
               'the-screen', 'the-particles', 'the-glyphs', 'the-resonance',
               'the-wear')
order by slug;

-- one tier each, the atom only:
select slug, atom_id is not null as has_atom,
       molecule_id is null as no_molecule,
       organism_id is null as no_organism
from public.awen
where slug in ('the-effect', 'the-graph', 'the-dynamics', 'the-transition',
               'the-screen', 'the-particles', 'the-glyphs', 'the-resonance',
               'the-wear')
order by slug;

-- each face of this paper should have exactly one wearer:
select icon_emoji, count(*) as wearers, string_agg(name, ' · ' order by name) as who
from public.awen
where icon_emoji in ('🗒️', '🔢', '🎢', '🔦', '🪟', '🫧', '🪪', '👀', '🔋')
group by icon_emoji
order by icon_emoji;

-- the atoms these rows ride, with the modifiers that carry the plurals:
select atom_word, category_name, atom_type, state, status, modifiers, pascal_case
from public.atoms
where atom_word in ('effect', 'graph', 'dynamic', 'transition', 'screen',
                    'particle', 'glyph', 'resonance', 'wear')
order by atom_word;

